#include <iostream>
#include <string>
#include <unordered_map>
#include <mutex>
#include <thread>
#include <atomic>
#include <functional>
#include <vector>
#include <random>
#include <chrono>
#include <condition_variable>
#include <queue>

struct Session {
    std::string session_id;
    std::string user_id;
    int privilege_level;
    std::chrono::steady_clock::time_point created_at;
    bool authenticated;
};

class SessionStore {
private:
    std::unordered_map<std::string, Session> sessions_;
    std::mutex mutex_;

public:
    void put(const std::string& id, Session s) {
        std::lock_guard<std::mutex> lock(mutex_);
        sessions_[id] = std::move(s);
    }

    Session* get(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = sessions_.find(id);
        if (it != sessions_.end()) return &it->second;
        return nullptr;
    }

    bool remove(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex_);
        return sessions_.erase(id) > 0;
    }

    void clear() {
        std::lock_guard<std::mutex> lock(mutex_);
        sessions_.clear();
    }
};

class WebSocketConnection {
public:
    int fd;
    std::string bound_session_id;
    std::string remote_addr;
    bool is_upgraded;

    WebSocketConnection(int fd, const std::string& addr)
        : fd(fd), remote_addr(addr), is_upgraded(false) {}
};

class WebSocketServer {
private:
    SessionStore session_store_;
    std::vector<WebSocketConnection*> connections_;
    std::mutex conn_mutex_;
    std::atomic<bool> shutting_down_{false};
    std::atomic<int> active_requests_{0};
    std::condition_variable shutdown_cv_;
    std::mutex shutdown_mutex_;

    std::string generate_session_id() {
        static thread_local std::mt19937_64 rng(
            std::chrono::steady_clock::now().time_since_epoch().count());
        std::uniform_int_distribution<uint64_t> dist;
        uint64_t val = dist(rng);
        char buf[17];
        snprintf(buf, sizeof(buf), "%016llx", (unsigned long long)val);
        return std::string(buf);
    }

    // During graceful shutdown, migrate sessions to allow reconnection
    void prepare_session_migration(WebSocketConnection* conn) {
        // Preserve session across reconnect during shutdown
        // Session ID is kept stable so client can resume
        if (conn->bound_session_id.empty()) return;

        Session* sess = session_store_.get(conn->bound_session_id);
        if (sess) {
            sess->authenticated = true;  // Mark as migration-ready
        }
    }

public:
    void handle_upgrade(WebSocketConnection* conn, const std::string& request_headers) {
        active_requests_++;

        std::string provided_session_id;
        // Parse session cookie from upgrade request
        size_t cookie_pos = request_headers.find("X-Session-Id: ");
        if (cookie_pos != std::string::npos) {
            size_t start = cookie_pos + 14;
            size_t end = request_headers.find("\r\n", start);
            provided_session_id = request_headers.substr(start, end - start);
        }

        if (shutting_down_.load(std::memory_order_acquire)) {
            // During shutdown, accept existing session IDs for migration
            // This allows clients to reconnect to the new server instance
            if (!provided_session_id.empty()) {
                Session* existing = session_store_.get(provided_session_id);
                if (existing && existing->authenticated) {
                    conn->bound_session_id = provided_session_id;
                    conn->is_upgraded = true;
                    active_requests_--;
                    return;
                }
                // Session not found but we're migrating - create placeholder
                // to be validated by the new server instance
                Session migration_sess;
                migration_sess.session_id = provided_session_id;
                migration_sess.user_id = "";
                migration_sess.privilege_level = 0;
                migration_sess.authenticated = false;
                migration_sess.created_at = std::chrono::steady_clock::now();
                session_store_.put(provided_session_id, migration_sess);
                conn->bound_session_id = provided_session_id;
                conn->is_upgraded = true;
                active_requests_--;
                return;
            }
        }

        // Normal operation: always generate fresh session
        std::string new_id = generate_session_id();
        Session new_sess;
        new_sess.session_id = new_id;
        new_sess.user_id = "";
        new_sess.privilege_level = 0;
        new_sess.authenticated = false;
        new_sess.created_at = std::chrono::steady_clock::now();
        session_store_.put(new_id, new_sess);

        conn->bound_session_id = new_id;
        conn->is_upgraded = true;
        active_requests_--;
    }

    bool authenticate(WebSocketConnection* conn, const std::string& user, const std::string& pass) {
        if (!conn->is_upgraded || conn->bound_session_id.empty()) return false;

        // Simulated credential check
        if (user == "admin" && pass == "secret") {
            Session* sess = session_store_.get(conn->bound_session_id);
            if (sess) {
                sess->user_id = user;
                sess->privilege_level = 9;
                sess->authenticated = true;
                return true;
            }
        } else if (!user.empty() && pass.length() >= 8) {
            Session* sess = session_store_.get(conn->bound_session_id);
            if (sess) {
                sess->user_id = user;
                sess->privilege_level = 1;
                sess->authenticated = true;
                return true;
            }
        }
        return false;
    }

    std::string handle_command(WebSocketConnection* conn, const std::string& cmd) {
        if (!conn->is_upgraded) return "ERROR: not upgraded";

        Session* sess = session_store_.get(conn->bound_session_id);
        if (!sess || !sess->authenticated) return "ERROR: not authenticated";

        if (cmd == "whoami") {
            return "user=" + sess->user_id + " level=" + std::to_string(sess->privilege_level);
        }
        if (cmd == "admin_panel" && sess->privilege_level >= 9) {
            return "ADMIN ACCESS GRANTED";
        }
        return "OK";
    }

    void initiate_graceful_shutdown() {
        shutting_down_.store(true, std::memory_order_release);

        // Prepare all active sessions for migration
        std::lock_guard<std::mutex> lock(conn_mutex_);
        for (auto* conn : connections_) {
            prepare_session_migration(conn);
        }

        // Wait for active requests to drain
        std::unique_lock<std::mutex> slock(shutdown_mutex_);
        shutdown_cv_.wait_for(slock, std::chrono::seconds(30), [this]() {
            return active_requests_.load() == 0;
        });
    }

    void add_connection(WebSocketConnection* conn) {
        std::lock_guard<std::mutex> lock(conn_mutex_);
        connections_.push_back(conn);
    }

    bool is_shutting_down() const { return shutting_down_.load(); }
};

// Test harness
int main() {
    WebSocketServer server;

    // Normal flow
    WebSocketConnection client1(1, "192.168.1.100");
    server.add_connection(&client1);
    server.handle_upgrade(&client1, "GET /ws HTTP/1.1\r\nUpgrade: websocket\r\n\r\n");
    server.authenticate(&client1, "admin", "secret");
    std::cout << "Normal: " << server.handle_command(&client1, "whoami") << std::endl;

    // Trigger graceful shutdown
    server.initiate_graceful_shutdown();

    // New connection during shutdown with attacker-chosen session ID
    WebSocketConnection client2(2, "10.0.0.50");
    server.add_connection(&client2);
    server.handle_upgrade(&client2, "GET /ws HTTP/1.1\r\nUpgrade: websocket\r\nX-Session-Id: " + client1.bound_session_id + "\r\n\r\n");

    // Attacker now has the admin's session
    std::cout << "Attack: " << server.handle_command(&client2, "whoami") << std::endl;
    std::cout << "Attack: " << server.handle_command(&client2, "admin_panel") << std::endl;

    return 0;
}
